function render(target){if(!data)return;if(target!=='import')pending=null;if(target!=='labs'){editId=null;labDetail=null;labAdd=false;labNotice=''}if(target!=='meds')medEditId=null;if(target!=='systems')selectedSystem='';page=target;document.querySelectorAll('nav button').forEach(b=>b.dataset.page===page?b.setAttribute('aria-current','page'):b.removeAttribute('aria-current'));const c=$('content'),rows=active('labs');c.replaceChildren();switch(page){case'home':home(c,rows);break;case'labs':labs(c,rows);break;case'systems':systemsPage(c,rows);break;case'import':importPage(c);break;case'journal':journal(c);break;case'timeline':timelinePage(c);break;case'meds':medsPage(c);break;case'science':scienceNew(c);break;case'settings':settings(c);break}c.focus({preventScroll:true})}

