 const p=panel('Referans görünümü','Bu tercih sadece ek bilgiyi açar veya kapatır. Kaydedilen rapor aralıklarını değiştirmez.');const form=el('form');const select=fieldSelect(form,'mode','Aktif profilin görünümü',[['report','Laboratuvar raporu'],['context','Laboratuvar raporu + bilimsel bağlam']],currentProfile().referenceMode);
