function nonHdlPanel(rows){
 const p=panel('Non-HDL kolesterol hesaplayıcı','Total kolesterol − HDL kolesterol. Aynı örnekten gelen, aynı birimde iki ölçümü seç. Hesaplanan değer raporun özgün sonucu olarak kaydedilmez.');
 const tc=rows.filter(r=>r.testId==='tc'&&exact(r)),hdl=rows.filter(r=>r.testId==='hdl'&&exact(r));
 if(!tc.length||!hdl.length){p.append(el('div','Hesaplamak için total kolesterol ve HDL kaydı gerekli.','empty'));return p}
 const label=r=>r.date+' · '+resultLabel(r)+' · '+(r.lab||'Lab. belirsiz');
 const first=fieldSelect(p,'tc','Total kolesterol',[['','Ölçümü seç'],...tc.map(r=>[r.id,label(r)])],'');
 const second=fieldSelect(p,'hdl','HDL kolesterol',[['','Ölçümü seç'],...hdl.map(r=>[r.id,label(r)])],'');
 const l=el('label',undefined,'checkrow'),check=el('input');check.type='checkbox';l.append(check,el('span','İki sonucun aynı kan örneğine ait olduğunu doğruladım.'));p.append(l);
 const result=el('div',undefined,'calc-result');result.setAttribute('role','status');function draw(){result.replaceChildren();if(!first.value||!second.value||!check.checked){result.append(el('p','Ölçümleri ve aynı örnek koşulunu doğrula.','muted'));return}
 const calc=nonHDL(tc.find(r=>r.id===first.value),hdl.find(r=>r.id===second.value),check.checked);if(!calc){result.append(el('p','Tarih, birim, laboratuvar veya değer uyumsuz. Hesaplama yapılmadı.','message'));return}
 result.append(el('p','HESAPLANAN GÖSTERGE','eyebrow'),el('div',calc.value+' '+calc.unit,'metric'),el('p',calc.date+' · '+calc.formula),el('p','Tedavi hedefi veya klinik risk puanı değildir.','muted'));const a=el('a','ACC/AHA 2026 · Bölüm 3.2');a.href=calc.source;a.target='_blank';a.rel='noopener noreferrer';result.append(a)}
 first.onchange=second.onchange=()=>{check.checked=false;draw()};check.onchange=draw;p.append(result);draw();return p;
}
